package api.publica;
import com.fasterxml.jackson.databind.*;import com.sun.net.httpserver.*;import config.ConfiguracionMercadoPago;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import pagos.*;import servicio.*;import negocio.EventoPago;
public class MercadoPagoWebhookHandler {public static final String RUTA="/api/publica/pagos/mercado-pago/webhook";private final SeguridadApiPublica seguridad;private final ObjectMapper mapper;private final ValidadorFirmaMercadoPago firmas;private final WebhookMercadoPagoService servicio;private final AuditoriaWebhookMercadoPagoService auditoria;public MercadoPagoWebhookHandler(SeguridadApiPublica s,ObjectMapper m,ConfiguracionMercadoPago c){this(s,m,new ValidadorFirmaMercadoPago(c.webhookSecret()),new WebhookMercadoPagoService(new dao.OrdenPagoDAOMySQL(),PasarelaPagoFactory.crear(c),new AcreditacionOrdenPagoTransaccionalService()),new AuditoriaWebhookMercadoPagoService());}public MercadoPagoWebhookHandler(SeguridadApiPublica s,ObjectMapper m,ValidadorFirmaMercadoPago f,WebhookMercadoPagoService v){this(s,m,f,v,new AuditoriaWebhookMercadoPagoService());}public MercadoPagoWebhookHandler(SeguridadApiPublica s,ObjectMapper m,ValidadorFirmaMercadoPago f,WebhookMercadoPagoService v,AuditoriaWebhookMercadoPagoService a){if(s==null||m==null||f==null||v==null||a==null)throw new IllegalArgumentException("Las dependencias del webhook son obligatorias.");seguridad=s;mapper=m;firmas=f;servicio=v;auditoria=a;}public boolean puedeProcesar(String r){return RUTA.equals(r);}public void procesar(HttpExchange x,String metodo,String operacionId)throws IOException{if(!"POST".equals(metodo)){responder(x,405,Map.of("codigo","METODO_NO_PERMITIDO","operacionId",operacionId));return;}byte[] bytes=seguridad.leerCuerpoLimitado(x.getRequestBody());String payload=new String(bytes,StandardCharsets.UTF_8),requestId=x.getRequestHeaders().getFirst("x-request-id"),signature=x.getRequestHeaders().getFirst("x-signature");JsonNode body;try{body=mapper.readTree(bytes);}catch(RuntimeException|IOException ex){EventoPago e=auditoria.recibir(requestId,null,payload,false);auditoria.error(e,"JSON invalido.");responder(x,400,Map.of("codigo","JSON_INVALIDO","operacionId",operacionId));return;}String tipo=texto(body,"type"),dataId=body.path("data").path("id").asText(null);if(!"payment".equals(tipo)||dataId==null){EventoPago e=auditoria.recibir(requestId,dataId,payload,false);auditoria.error(e,"Webhook invalido.");responder(x,400,Map.of("codigo","WEBHOOK_INVALIDO","operacionId",operacionId));return;}boolean valida=firmas.validar(signature,requestId,dataId);EventoPago entrega=auditoria.recibir(requestId,dataId,payload,valida);if(!valida){auditoria.error(entrega,"Firma invalida.");responder(x,401,Map.of("codigo","FIRMA_INVALIDA","operacionId",operacionId));return;}try{var r=servicio.procesar(dataId,payload);auditoria.procesado(entrega,"Pago consultado. Estado externo: "+r.estadoExterno()+". Procesado: "+r.procesado()+".");responder(x,200,Map.of("recibido",true,"procesado",r.procesado(),"estado",r.estadoExterno(),"operacionId",operacionId));}catch(WebhookMercadoPagoService.ConflictoPagoException e){auditoria.error(entrega,"Pago incompatible: "+e.getMessage());responder(x,409,Map.of("codigo","PAGO_INCOMPATIBLE","operacionId",operacionId));}catch(RuntimeException e){auditoria.error(entrega,"Error de procesamiento: "+e.getClass().getSimpleName()+".");throw e;}}private String texto(JsonNode n,String k){JsonNode v=n.get(k);return v==null||v.isNull()?null:v.asText();}private void responder(HttpExchange x,int estado,Object cuerpo)throws IOException{byte[] b=mapper.writeValueAsBytes(cuerpo);x.getResponseHeaders().set("Content-Type","application/json; charset=UTF-8");x.sendResponseHeaders(estado,b.length);try(OutputStream o=x.getResponseBody()){o.write(b);}}}